const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Memphis, TN location on Mississippi River
  const memphis = ee.Geometry.Point([-90.03, 35.15]);
  const buffer = 5000; // 5km buffer around point
  const roi = memphis.buffer(buffer);

  // Date ranges (±3 days to catch imagery)
  const date1Start = '2014-02-24';
  const date1End = '2014-03-02';
  const date2Start = '2019-02-22';
  const date2End = '2019-03-02';

  // Try Sentinel-1 first (works through clouds)
  const s1_2014 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date1Start, date1End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'));

  const s1_2019 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(roi)
    .filterDate(date2Start, date2End)
    .filter(ee.Filter.eq('instrumentMode', 'IW'));

  const size2014_s1 = s1_2014.size().getInfo();
  const size2019_s1 = s1_2019.size().getInfo();

  print(`Sentinel-1 2014: ${size2014_s1} images, 2019: ${size2019_s1} images`);

  let water2014, water2019, count2014, count2019;

  // If Sentinel-1 insufficient, try Landsat 8
  if (size2014_s1 > 0 && size2019_s1 > 0) {
    // Use Sentinel-1: water = low VH/VV ratio (typically < -11 dB)
    const maskWaterS1 = function(img) {
      const ratio = img.select('VH').divide(img.select('VV')).log10().multiply(10);
      return img.addBands(ratio.rename('waterMask')).select('waterMask');
    };

    water2014 = s1_2014.map(maskWaterS1).median().lt(-12); // Water threshold
    water2019 = s1_2019.map(maskWaterS1).median().lt(-12);

  } else {
    // Fallback to Landsat 8
    const l8_2014 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date1Start, date1End);

    const l8_2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date2Start, date2End);

    const size2014_l8 = l8_2014.size().getInfo();
    const size2019_l8 = l8_2019.size().getInfo();

    print(`Landsat-8 2014: ${size2014_l8} images, 2019: ${size2019_l8} images`);

    if (size2014_l8 === 0 || size2019_l8 === 0) {
      print('No data for one or both dates (Sentinel-1 and Landsat-8 failed)');
      print('C1');
      return;
    }

    // NDWI for water detection
    const ndwi2014 = l8_2014.map(img => {
      const ndwi = img.normalizedDifference(['SR_B3', 'SR_B5']);
      return ndwi.gt(0.3); // Water threshold
    }).max();

    const ndwi2019 = l8_2019.map(img => {
      const ndwi = img.normalizedDifference(['SR_B3', 'SR_B5']);
      return ndwi.gt(0.3);
    }).max();

    water2014 = ndwi2014;
    water2019 = ndwi2019;
  }

  // Calculate water extent (pixel count)
  const stats2014 = water2014.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  count2014 = stats2014['waterMask'] !== undefined ? stats2014['waterMask'] : 
              (stats2014 && typeof stats2014 === 'object' ? Object.values(stats2014)[0] : 0);
  count2019 = stats2019['waterMask'] !== undefined ? stats2019['waterMask'] : 
              (stats2019 && typeof stats2019 === 'object' ? Object.values(stats2019)[0] : 0);

  print(`Water pixels 2014: ${count2014}, 2019: ${count2019}`);

  // Validation
  if (count2014 === null || count2019 === null || count2014 === undefined || count2019 === undefined) {
    print('C3');
    return;
  }

  if (count2014 === 0 && count2019 === 0) {
    print('No valid water pixels detected in either date');
    print('C2');
    return;
  }

  // Answer: Compare extents
  if (count2019 > count2014) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
